551	+  template: `
552	+    <button
553	+      #trigger
554	+      type="button"
555	+      class="trigger"
556	+      cdkOverlayOrigin
557	+      #triggerOrigin="cdkOverlayOrigin"
558	+      aria-haspopup="dialog"
559	+      [attr.aria-expanded]="isOpen()"
560	+      [attr.aria-controls]="isOpen() ? dialogId : null"
561	+      [attr.aria-label]="triggerName()"
562	+      [disabled]="isDisabled()"
