566	+        <app-icon class="calendar-icon" name="calendar" [size]="18" />
567	+        <span aria-live="polite">{{ weekLabel() }}</span>
568	+      </span>
569	+      <app-icon class="chevron-icon" [name]="isOpen() ? 'chevron-up' : 'chevron-down'" />
570	+    </button>
571	+
572	+    <ng-template
573	+      cdkConnectedOverlay
574	+      [cdkConnectedOverlayOrigin]="triggerOrigin"
575	+      [cdkConnectedOverlayOpen]="isOpen()"
576	+      [cdkConnectedOverlayPositions]="popoverPositions"
577	+      (attach)="focusSelectedWeek()"
578	+      (detach)="close()"
579	+      (overlayOutsideClick)="closeOnOutsideClick($event)"
580	+    >
