582	+        <mat-calendar
583	+          [startAt]="selectedMonday()"
584	+          [selected]="selectedMonday()"
585	+          [minDate]="earliestMonday()"
586	+          [maxDate]="latestCompleteMonday()"
587	+          [dateFilter]="isSelectableMonday"
588	+          [dateClass]="selectedWeekClass"
589	+          (_userSelection)="choose($event.value)"
