608	+    .trigger:disabled { background: var(--color-disabled-fill); border-color: var(--color-disabled-border); color: var(--color-ink-2); cursor: not-allowed; }
609	+    .trigger-label { display: flex; align-items: center; gap: 10px; font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; }
610	+    .chevron-icon { color: var(--color-ink-2); }
