614	+  `,
615	+})
616	+export class WeekPicker {
617	+  readonly week = input.required<WeekRange>();
618	+  readonly earliestWeek = input.required<string>();
619	+  readonly latestCompleteWeek = input.required<string>();
620	+
621	+  readonly weekSelected = output<string>();
622	+
623	+  private readonly injector = inject(Injector);
624	+  private readonly trigger = viewChild.required<ElementRef<HTMLButtonElement>>('trigger');
625	+  private readonly calendar = viewChild(MatCalendar);
626	+
627	+  protected readonly dialogId = `week-picker-dialog-${nextDialogId++}`;
628	+  protected readonly popoverPositions: ConnectedPosition[] = [
629	+    { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 8 },
630	+    { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -8 },
631	+  ];
632	+
633	+  protected readonly isOpen = signal(false);
634	+  protected readonly isDisabled = computed(() => this.earliestWeek() === this.latestCompleteWeek());
635	+  protected readonly weekLabel = computed(() => formatWeekRange(this.week().start, this.week().end));
636	+  protected readonly triggerName = computed(() => `${this.weekLabel()}, choose week`);
637	+  protected readonly selectableWeeksLabel = computed(() => formatSelectableWeeks(this.earliestWeek(), this.latestCompleteWeek()));
638	+  protected readonly isLatestWeekSelected = computed(() => this.week().start === this.latestCompleteWeek());
639	+  protected readonly selectedMonday = computed(() => parseISO(this.week().start));
640	+  protected readonly selectedSunday = computed(() => parseISO(this.week().end));
641	+  protected readonly earliestMonday = computed(() => parseISO(this.earliestWeek()));
642	+  protected readonly latestCompleteMonday = computed(() => parseISO(this.latestCompleteWeek()));
643	+
644	+  protected readonly isSelectableMonday: DateFilterFn<Date> = (day) =>
645	+    day !== null && isMonday(day) && isWithinInterval(day, { start: this.earliestMonday(), end: this.latestCompleteMonday() });
646	+
647	+  protected readonly selectedWeekClass: MatCalendarCellClassFunction<Date> = (day, view) =>
648	+    view === 'month' && !isMonday(day) && isWithinInterval(day, { start: this.selectedMonday(), end: this.selectedSunday() })
649	+      ? SELECTED_WEEK_CLASS
650	+      : '';
651	+
652	+  protected toggle(): void {
653	+    if (this.isOpen()) {
654	+      this.close();
655	+    } else {
656	+      this.isOpen.set(true);
657	+    }
658	+  }
659	+
660	+  protected close(): void {
661	+    if (!this.isOpen()) {
662	+      return;
663	+    }
664	+    this.isOpen.set(false);
665	+    this.trigger().nativeElement.focus();
666	+  }
667	+
668	+  protected closeOnOutsideClick(event: MouseEvent): void {
669	+    if (!(event.target instanceof Node && this.trigger().nativeElement.contains(event.target))) {
670	+      this.close();
671	+    }
672	+  }
673	+
674	+  protected focusSelectedWeek(): void {
675	+    afterNextRender(() => this.calendar()?.focusActiveCell(), { injector: this.injector });
676	+  }
677	+
678	+  protected chooseLatestWeek(): void {
679	+    this.close();
680	+    this.weekSelected.emit(this.latestCompleteWeek());
681	+  }
682	+
683	+  protected choose(day: Date | null): void {
684	+    if (day === null) {
685	+      return;
686	+    }
687	+    const chosenWeek = format(day, ISO_DATE_FORMAT);
688	+    this.close();
689	+    if (chosenWeek !== this.week().start) {
690	+      this.weekSelected.emit(chosenWeek);
691	+    }
692	+  }
693	+}
