+  }
+
+  .mat-calendar-body-cell-container:has(.week-picker-selected-week) { background: var(--color-fill-muted); }
+
+  .mat-calendar-body-cell-container:has(.week-picker-selected-week):nth-child(7) {
+    background: linear-gradient(to left, transparent 50%, var(--color-fill-muted) 50%);
+  }
+
+  .week-picker-selected-week > .mat-calendar-body-cell-content { color: var(--color-ink-2); }
+
+  .mat-calendar-body-cell-container:nth-child(7) .week-picker-selected-week > .mat-calendar-body-cell-content {
+    background: var(--color-fill-muted);
+  }
+
+  .helper {
+    margin-top: 12px;
+    padding-top: 12px;
+    border-top: 1px solid var(--color-line-soft);
+    font-size: 13px;
+    line-height: 18px;
+    color: var(--color-ink-2);
+
+    p { margin: 0; }
+    p + p { margin-top: 2px; }
+  }
+
+  .footer { margin-top: 14px; display: flex; }
+
+  .latest-week {
+    height: 44px;
+    padding: 0 16px;
+    border: 1px solid var(--color-control-border);
+    border-radius: 8px;
+    background: var(--color-surface);
+    font: inherit;
+    font-size: 14px;
+    font-weight: 500;
+    color: var(--color-ink);
+    cursor: pointer;
+    white-space: nowrap;
+
+    &:disabled {
+      border-color: var(--color-disabled-border);
+      background: var(--color-disabled-fill);
+      color: var(--color-disabled-ink);
+      cursor: not-allowed;
+    }
+  }
+}
+
+@keyframes week-picker-open {
+  from { opacity: 0; transform: scale(0.97); }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .week-picker-dialog { animation: none; }
+}

